<?php require 'config.php';
if (($_SESSION['user']['role'] ?? '') === 'admin') { header('Location: admin_gradebook.php'); exit; }
require_role('faculty'); $title='Gradebook'; $fid=(int)$_SESSION['user']['id']; $offering=(int)($_GET['offering']??0); $assessment=trim($_POST['assessment']??''); $max=(float)($_POST['max_score']??100); $notice='';
$q=$pdo->prepare("SELECT o.id,s.code,s.name,o.section FROM subject_offerings o JOIN subjects s ON s.id=o.subject_id WHERE o.faculty_id=? ORDER BY s.code,o.section");$q->execute([$fid]);$classes=$q->fetchAll();if(!$offering&&$classes)$offering=(int)$classes[0]['id'];
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='save_grade'){if($assessment==='')$notice='Assessment name is required.';else{try{$check=$pdo->prepare("SELECT id FROM subject_offerings WHERE id=? AND faculty_id=?");$check->execute([$offering,$fid]);if(!$check->fetch())throw new Exception('Class not found.');$ins=$pdo->prepare("INSERT INTO gradebook_entries(offering_id,student_id,assessment,score,max_score,feedback,recorded_by) VALUES(?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE score=VALUES(score),max_score=VALUES(max_score),feedback=VALUES(feedback),recorded_by=VALUES(recorded_by)");foreach($_POST['score']??[] as $sid=>$score){$score=trim((string)$score);if($score==='')continue;$ins->execute([$offering,(int)$sid,$assessment,(float)$score,$max,trim($_POST['feedback'][$sid]??''),$fid]);} $notice='Gradebook saved.';}catch(Throwable $e){$notice='Unable to save grades: '.$e->getMessage();}}}
$selected=null;$roster=[];$assessments=[];if($offering){$q=$pdo->prepare("SELECT o.*,s.code,s.name FROM subject_offerings o JOIN subjects s ON s.id=o.subject_id WHERE o.id=? AND o.faculty_id=?");$q->execute([$offering,$fid]);$selected=$q->fetch();if($selected){$r=$pdo->prepare("SELECT u.id,u.name,u.student_id FROM enrollments e JOIN users u ON u.id=e.student_id WHERE e.offering_id=? AND e.status='approved' ORDER BY u.name");$r->execute([$offering]);$roster=$r->fetchAll();$a=$pdo->prepare("SELECT DISTINCT assessment FROM gradebook_entries WHERE offering_id=? ORDER BY assessment");$a->execute([$offering]);$assessments=$a->fetchAll(PDO::FETCH_COLUMN);}}
require 'header.php'; ?><section class="section"><div class="section-intro"><div><span class="eyebrow">FACULTY</span><h2>Gradebook</h2><p class="muted">Record assessment scores and feedback for your students.</p></div></div><?php if($notice):?><div class="success"><?=e($notice)?></div><?php endif;?><form class="filter-bar" method="get"><label>Class <select name="offering" onchange="this.form.submit()"><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$offering===$c['id']?'selected':''?>><?=e($c['code'].' · '.$c['section'])?></option><?php endforeach;?></select></label><button class="btn">Load</button></form><?php if($selected):?><form method="post"><input type="hidden" name="action" value="save_grade"><div class="gradebook-head"><label>Assessment <input required name="assessment" placeholder="Quiz 1, Midterm, Activity..." value="<?=e($assessment)?>"></label><label>Max Score <input type="number" name="max_score" min="1" step="0.01" value="<?=e($max)?>"></label></div><div class="table-scroll"><table class="table"><tr><th>Student</th><th>ID</th><th>Score</th><th>Feedback</th></tr><?php foreach($roster as $r):$old=$pdo->prepare("SELECT score,feedback FROM gradebook_entries WHERE offering_id=? AND student_id=? AND assessment=? LIMIT 1");$old->execute([$offering,$r['id'],$assessment]);$ov=$old->fetch()?:[];?><tr><td><b><?=e($r['name'])?></b></td><td><?=e($r['student_id']?:'—')?></td><td><input type="number" name="score[<?=$r['id']?>]" min="0" max="<?=e($max)?>" step="0.01" value="<?=e($ov['score']??'')?>"></td><td><input name="feedback[<?=$r['id']?>]" value="<?=e($ov['feedback']??'')?>" placeholder="Optional feedback"></td></tr><?php endforeach;?></table></div><button class="btn" style="margin-top:14px">Save Gradebook</button></form><div class="info-box" style="margin-top:16px"><b>Existing assessments</b><p><?=e($assessments?implode(' · ',$assessments):'None yet')?></p></div><?php endif;?></section><?php require 'footer.php'; ?>
